package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sort parameter against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "id"
	}

	// Build query - category is validated via prepared statement
	// but we need dynamic ORDER BY which can't be parameterized
	var query string
	var args []interface{}

	if minPrice != "" {
		// Developer note: minPrice is cast to numeric in SQL so injection via
		// this param would cause a cast error... right?
		query = fmt.Sprintf(
			"SELECT id, name, price, sku FROM products WHERE category = $1 AND price >= %s ORDER BY %s",
			minPrice, sortBy,
		)
		args = append(args, category)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, sku FROM products WHERE category = $1 ORDER BY %s",
			sortBy,
		)
		args = append(args, category)
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProduct uses parameterized query (safe)
func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, price, sku FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s query=%s", r.RemoteAddr, r.Method, r.URL.Path, r.URL.RawQuery)
		// Truncate extremely long query strings (DoS protection)
		if len(r.URL.RawQuery) > 2048 {
			http.Error(w, "Request URI too long", http.StatusRequestURITooLong)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/products/search", searchProducts)
	mux.HandleFunc("/api/products/get", getProduct)
	mux.HandleFunc("/health", healthCheck)

	handler := loggingMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	_ = strings.NewReplacer() // unused import suppression
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
